Fragment Shader
1: 
2:   precision highp float;
3:   varying vec2 vUv;
4:   uniform float uTime;
5:   uniform vec2 uResolution;
6:   uniform vec2 uMouse;
7:   uniform float uTheme; // 0.0 = dark (#212121), 1.0 = light (#F6EFDD)
8: 
9:   void main() {
10:     vec2 aspect = vec2(uResolution.x / uResolution.y, 1.0);
11:     vec2 uv = vUv * aspect;
12:     vec2 mouse = uMouse * aspect;
13: 
14:     // Dot grid pitch (50 dots horizontally)
15:     float gridSize = 0.024;
16:     vec2 gridUv = fract(uv / gridSize) - 0.5;
17:     vec2 cellId = floor(uv / gridSize);
18: 
19:     // Distance from cell center to mouse
20:     vec2 cellCenter = (cellId + 0.5) * gridSize;
21:     float distToMouse = length(cellCenter - mouse);
22: 
23:     // Cursor displacement / warp (subtle repulsion)
24:     float warp = smoothstep(0.35, 0.0, distToMouse) * 0.12;
25:     vec2 dir = normalize(cellCenter - mouse + 0.0001);
26:     vec2 warpedUv = gridUv - dir * warp;
27: 
28:     // Dot radius: base 0.06, expands slightly near cursor
29:     float dotRadius = 0.07 + smoothstep(0.25, 0.0, distToMouse) * 0.05;
30:     float dot = 1.0 - smoothstep(dotRadius - 0.02, dotRadius + 0.02, length(warpedUv));
31: 
32:     // Base background colors
33:     vec3 bgDark = vec3(0.129, 0.129, 0.129);  // #212121
34:     vec3 bgLight = vec3(0.965, 0.937, 0.867); // #F6EFDD
35:     vec3 bg = mix(bgDark, bgLight, uTheme);
36: 
37:     // Dot base colors (hairline lines)
38:     vec3 dotBaseDark = vec3(0.24, 0.24, 0.24);  // #3D3D3D
39:     vec3 dotBaseLight = vec3(0.84, 0.80, 0.71); // #D6CDB5
40:     vec3 dotColor = mix(dotBaseDark, dotBaseLight, uTheme);
41: 
42:     // Red signal light at cursor: #FD142B
43:     vec3 redSignal = vec3(0.992, 0.078, 0.169);
44:     float redIntensity = smoothstep(0.38, 0.0, distToMouse);
45:     dotColor = mix(dotColor, redSignal, redIntensity * 0.95);
46: 
47:     // Composite final color
48:     vec3 finalColor = mix(bg, dotColor, dot);
49: 
50:     // Subtle radial glow around cursor
51:     float ambientGlow = smoothstep(0.45, 0.0, distToMouse) * 0.06;
52:     finalColor += redSignal * ambientGlow;
53: 
54:     gl_FragColor = vec4(finalColor, 1.0);
55:   }
